<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #10131a;
    --panel: #181e29;
    --board: #0b1016;
    --grid: #1d2733;
    --text: #e8f0f5;
    --muted: #93a4b7;
    --green: #5eea88;
    --green-dark: #26ae5c;
    --red: #ff5c72;
    --blue: #66b9ff;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background:
      radial-gradient(circle at 50% 10%, #202b3c 0%, transparent 42%),
      var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }

  .game-shell {
    width: min(94vw, 620px);
    padding: 22px;
    border: 1px solid #2a3544;
    border-radius: 20px;
    background: rgba(24, 30, 41, 0.95);
    box-shadow: 0 22px 70px rgba(0, 0, 0, 0.42);
  }

  .topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 16px;
  }

  h1 {
    margin: 0;
    font-size: 1.35rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  #score {
    padding: 8px 13px;
    border-radius: 999px;
    background: #101722;
    border: 1px solid #2b3a4b;
    color: var(--green);
    font-weight: 800;
    font-variant-numeric: tabular-nums;
  }

  .board-wrap {
    position: relative;
    width: 100%;
    aspect-ratio: 1;
    overflow: hidden;
    border-radius: 12px;
    border: 2px solid #35465c;
    background: var(--board);
  }

  #snake {
    display: block;
    width: 100%;
    height: 100%;
    min-width: 400px;
    min-height: 400px;
    background: var(--board);
  }

  .controls {
    display: flex;
    gap: 10px;
    margin-top: 16px;
  }

  button {
    flex: 1;
    padding: 11px 12px;
    border: 1px solid #394c62;
    border-radius: 10px;
    background: #243244;
    color: var(--text);
    cursor: pointer;
    font: inherit;
    font-weight: 700;
    transition: transform 120ms ease, background 120ms ease;
  }

  button:hover { background: #30425a; }
  button:active { transform: translateY(1px); }

  #start {
    background: #176b3a;
    border-color: #319759;
  }

  #start:hover { background: #218549; }

  .hint {
    margin: 14px 0 0;
    text-align: center;
    color: var(--muted);
    font-size: 0.88rem;
  }

  kbd {
    padding: 2px 5px;
    border-radius: 4px;
    border: 1px solid #405269;
    background: #101722;
    color: #dce8f2;
    font-family: inherit;
    font-size: 0.82em;
  }

  @media (max-width: 460px) {
    .game-shell { padding: 14px; }
    #snake { min-width: 400px; min-height: 400px; }
    .board-wrap { overflow: auto; }
  }
</style>
</head>
<body>
  <main class="game-shell">
    <div class="topbar">
      <h1>Snake</h1>
      <div id="score">Score: 0</div>
    </div>

    <div class="board-wrap">
      <canvas id="snake" width="520" height="520" aria-label="Snake game board"></canvas>
    </div>

    <div class="controls">
      <button id="start" type="button">Start</button>
      <button id="pause" type="button">Pause</button>
      <button id="reset" type="button">Reset</button>
    </div>

    <p class="hint">Steer with the <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> arrow keys</p>
  </main>

<script>
(() => {
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const startBtn = document.getElementById('start');
  const pauseBtn = document.getElementById('pause');
  const resetBtn = document.getElementById('reset');

  const w = 20;
  const h = 20;
  const directions = {
    up: [0, -1],
    down: [0, 1],
    left: [-1, 0],
    right: [1, 0]
  };
  const opposite = {
    up: 'down',
    down: 'up',
    left: 'right',
    right: 'left'
  };

  let body = [];
  let currentDir = 'right';
  let queuedDir = null;
  let foodCell = [15, 10];
  let points = 0;
  let isAlive = true;
  let timer = null;

  function updateScore() {
    scoreEl.textContent = 'Score: ' + points;
  }

  function sameCell(a, b) {
    return a[0] === b[0] && a[1] === b[1];
  }

  function isOnSnake(x, y) {
    return body.some(part => part[0] === x && part[1] === y);
  }

  function placeRandomFood() {
    const free = [];
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        if (!isOnSnake(x, y)) free.push([x, y]);
      }
    }
    foodCell = free.length ? free[Math.floor(Math.random() * free.length)] : null;
  }

  function roundedRect(x, y, width, height, radius) {
    const r = Math.min(radius, width / 2, height / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + width, y, x + width, y + height, r);
    ctx.arcTo(x + width, y + height, x, y + height, r);
    ctx.arcTo(x, y + height, x, y, r);
    ctx.arcTo(x, y, x + width, y, r);
    ctx.closePath();
  }

  function draw() {
    const cw = canvas.width;
    const ch = canvas.height;
    const cellW = cw / w;
    const cellH = ch / h;

    ctx.clearRect(0, 0, cw, ch);
    ctx.fillStyle = '#0b1016';
    ctx.fillRect(0, 0, cw, ch);

    ctx.strokeStyle = '#1d2733';
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x++) {
      ctx.beginPath();
      ctx.moveTo(x * cellW, 0);
      ctx.lineTo(x * cellW, ch);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellH);
      ctx.lineTo(cw, y * cellH);
      ctx.stroke();
    }

    if (foodCell) {
      const fx = foodCell[0] * cellW + cellW / 2;
      const fy = foodCell[1] * cellH + cellH / 2;
      const radius = Math.min(cellW, cellH) * 0.29;

      ctx.fillStyle = '#ff5c72';
      ctx.beginPath();
      ctx.arc(fx, fy, radius, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#ffd5db';
      ctx.beginPath();
      ctx.arc(fx - radius * 0.28, fy - radius * 0.3, radius * 0.23, 0, Math.PI * 2);
      ctx.fill();
    }

    body.forEach((part, index) => {
      const inset = index === 0 ? 2 : 3;
      const x = part[0] * cellW + inset;
      const y = part[1] * cellH + inset;
      const bw = cellW - inset * 2;
      const bh = cellH - inset * 2;

      ctx.fillStyle = index === 0 ? '#74f39b' : '#32bd67';
      roundedRect(x, y, bw, bh, Math.min(cellW, cellH) * 0.18);
      ctx.fill();

      if (index === 0) {
        const [dx, dy] = directions[currentDir];
        const eyeOffsetX = dx * cellW * 0.13;
        const eyeOffsetY = dy * cellH * 0.13;
        const sideX = dy * cellW * 0.16;
        const sideY = dx * cellH * 0.16;
        ctx.fillStyle = '#102318';
        for (const side of [-1, 1]) {
          ctx.beginPath();
          ctx.arc(
            part[0] * cellW + cellW / 2 + eyeOffsetX + side * sideX,
            part[1] * cellH + cellH / 2 + eyeOffsetY + side * sideY,
            Math.min(cellW, cellH) * 0.075,
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
      }
    });

    if (!isAlive) {
      ctx.fillStyle = 'rgba(5, 8, 12, 0.58)';
      ctx.fillRect(0, 0, cw, ch);
      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'center';
      ctx.font = 'bold 32px system-ui, sans-serif';
      ctx.fillText('Game Over', cw / 2, ch / 2 - 8);
      ctx.fillStyle = '#b9c9d7';
      ctx.font = '16px system-ui, sans-serif';
      ctx.fillText('Press Reset to play again', cw / 2, ch / 2 + 24);
    }
  }

  function reset() {
    stop();
    body = [[10, 10], [9, 10], [8, 10]];
    currentDir = 'right';
    queuedDir = null;
    points = 0;
    isAlive = true;
    placeRandomFood();
    updateScore();
    draw();
  }

  function tick() {
    if (!isAlive) return;

    if (queuedDir) {
      currentDir = queuedDir;
      queuedDir = null;
    }

    const [dx, dy] = directions[currentDir];
    const head = body[0];
    const next = [head[0] + dx, head[1] + dy];
    const eating = foodCell && sameCell(next, foodCell);

    const hitsWall = next[0] < 0 || next[0] >= w || next[1] < 0 || next[1] >= h;
    const collisionCheck = eating ? body : body.slice(0, -1);
    const hitsBody = collisionCheck.some(part => sameCell(part, next));

    if (hitsWall || hitsBody) {
      isAlive = false;
      stop();
      draw();
      return;
    }

    body.unshift(next);

    if (eating) {
      points++;
      updateScore();
      placeRandomFood();
    } else {
      body.pop();
    }

    draw();
  }

  function setDir(dir) {
    if (!directions[dir] || !isAlive) return;
    if (dir === opposite[currentDir]) return;
    queuedDir = dir;
  }

  function setFood(x, y) {
    const fx = Number(x);
    const fy = Number(y);
    if (!Number.isInteger(fx) || !Number.isInteger(fy)) return;
    if (fx < 0 || fx >= w || fy < 0 || fy >= h) return;
    foodCell = [fx, fy];
    draw();
  }

  function start() {
    if (!isAlive) return;
    if (timer) return;
    timer = window.setInterval(tick, 115);
  }

  function stop() {
    if (timer) {
      window.clearInterval(timer);
      timer = null;
    }
  }

  startBtn.addEventListener('click', start);
  pauseBtn.addEventListener('click', stop);
  resetBtn.addEventListener('click', reset);

  window.addEventListener('keydown', event => {
    const keyMap = {
      ArrowUp: 'up',
      ArrowDown: 'down',
      ArrowLeft: 'left',
      ArrowRight: 'right'
    };
    if (keyMap[event.key]) {
      event.preventDefault();
      setDir(keyMap[event.key]);
    } else if (event.key === ' ') {
      event.preventDefault();
      if (timer) stop();
      else start();
    }
  });

  window.game = {
    w,
    h,
    reset,
    tick,
    setDir,
    setFood,
    snake: () => body.map(part => [part[0], part[1]]),
    food: () => foodCell ? [foodCell[0], foodCell[1]] : null,
    alive: () => isAlive,
    score: () => points
  };

  reset();
})();
</script>
</body>
</html>
